local UICultivateEquipNode = Class('UICultivateEquipNode')


------------ import ------------
local KTool                 = CS.Engine.Lib.KTool
local cs_coroutine          = require 'XLua.cs_coroutine'
local Yielders              = CS.Engine.Lib.Yielders
local cardConfMgr           = CardConfMgr:GetInstance()
------------ import ------------

------------ define ------------
local EquipHeadNodeEnvPath  = "Game.UI.Cultivate.Equip.UICultivateEquipHeadNode"

local EffectType            = {
    Loop  = 1,  ---特效 已使核心激活（持续
    PutOn = 2,  ---特效 装备更换、装上（瞬时)
}

local EffectConfig = {
    [EffectType.Loop]  = "Effect/prefab/ui_prefab/UIFX_EquipNodeActiveLoop.prefab",
    [EffectType.PutOn] = "Effect/prefab/ui_prefab/UIFX_EquipNodePutOn.prefab",
}

------------ define ------------

function UICultivateEquipNode:__init()
    self.effectCos     = {}
    self.effectGos     = {}
    -- self.effectLoaders = {}
end

function UICultivateEquipNode:__delete()
    self.equipComp = nil
end

function UICultivateEquipNode:Awake()
    SetButtonAction(self.ImgBg.gameObject, Bind(self, self.OnClickEquipNodeAction))
    self:RefreshSelectState(false)
end


function UICultivateEquipNode:OnDestroy()
    for i, v in pairs(EffectType) do
        self:StopEffectCo(v)
        -- local loader = self.effectLoaders[v]
        -- if loader then
        --     loader:Release(true)
        -- end
    end
    self.uiSwiComps = nil
    self.effectGos = nil
    -- self.effectLoaders = nil

    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end


