---RefreshUI
---@param equipDojo EquipDojo       装备数据
---@param isActiveCore boolean      是否激活核心
---@param coreSuitId number         核心套装id
---@param isDisableEffect boolean   是否禁用激活特效
---@param isInstallPart boolean     是否是安装的部位  用于判断是否播放 put on 特效
function UICultivateEquipNode:RefreshUI(equipDojo, isActiveCore, coreSuitId, isDisableEffect, isInstallPart)
    local isOwnEquip = equipDojo ~= nil
    KTool.SetActive(self.ImgLvBg.gameObject, isOwnEquip)
    local rare, part
    local isActiveEquip = self:RefreshEquipHeadNode(equipDojo, isActiveCore, coreSuitId, isDisableEffect)
    -- KTool.SetActive(self.ImgLineActivated.gameObject, isActiveEquip)
    if isOwnEquip then
        local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
        rare = equipVo.rare
        part = equipVo.part
        self.TxtLv.text = equipDojo.level
    end
    self.ImgBg.Status = isOwnEquip and rare or 6
    -- self.TxtPart.Status = isOwnEquip and rare or 6

    if isInstallPart and isOwnEquip then
        self:PlayEquipEffect(EffectType.PutOn, nil, true)
    end

    if isActiveEquip then
        -- self.ImgLineActivated.Status = rare
        -- self.ImgLine2.Status = rare
        self:PlayEquipEffect(EffectType.Loop, part, false)
        --if not isDisableEffect then
        --end
    else
        self:StopEffectCo(EffectType.Loop)
        local go = self.effectGos[EffectType.Loop]
        if go then
            KTool.SetActive(go, false)
        end
    end
    return isActiveEquip
end

function UICultivateEquipNode:RefreshEquipHeadNode(equipDojo, isActiveedCore, coreSuitId, isDisableEffect)
    ---@type UICultivateEquipHeadNode
    local env = CfUtils.GetLuaScr(self.EquipPartNode, EquipHeadNodeEnvPath)
    if isNull(env) then
        return
    end
    env:SetIsHidePlusIcon(self.isHidePlusIcon)
    local isActiveEquip = env:RefreshUI(equipDojo, self:GetPart(), isActiveedCore, coreSuitId, isDisableEffect)
    --env:SetCallback(Bind(self, self.OnClickEquipNodeAction))
    return isActiveEquip
end

function UICultivateEquipNode:RefreshSelectState(isSelect)
    KTool.SetActive(self.ImgSelect.gameObject, isSelect)
end

function UICultivateEquipNode:StopEffectCo(effectType)
    local co = self.effectCos[effectType]
    if co then
        cs_coroutine.stop(co)
        self.effectCos[effectType] = nil
    end
end


function UICultivateEquipNode:PlayEquipEffect(effectType, part, isHide)
    self:StopEffectCo(effectType)
    local co = cs_coroutine.start(function()
        local animator = self.controller.gameObject:GetComponentInParent(typeof(CS.UnityEngine.Animator))
        if not isNull(animator) then
            cs_coroutine.yield_return(animator:WaitUntilAniCompleted())
        end
        local go = self.effectGos[effectType]
        if go == nil then
            if not isNull(self.controller) then
                go = GameUtils.LoadBundleAsync(EffectConfig[effectType], self.controller.gameObject, nil, true)
                self.effectGos[effectType] = go
                if part then
                    EquipUtils.SetEquipPartBgScale(go.transform, part)
                end
            end
        else
            KTool.SetActive(go.gameObject, true)
        end
        if isHide then
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
            KTool.SetActive(go.gameObject, false)
        end
        self.effectCos[effectType] = nil
    end)

    self.effectCos[EffectType.PutOn] = co
end

function UICultivateEquipNode:PlayAllEffect(part, rare)
    self:PlayEquipEffect(EffectType.PutOn, nil, true)
    self:PlayEquipEffect(EffectType.Loop, part, false)
    ---@type UICultivateEquipHeadNode
    local env = CfUtils.GetLuaScr(self.EquipPartNode, EquipHeadNodeEnvPath)
    if isNull(env) then
        return
    end
    env:PlayAllEffect(true, rare)
end


